// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";
contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 depositAmount, uint256 actorSeed) public {
        uint256 amount = bound(depositAmount, 1, type(uint96).max);
        address actor = vm.addr(uint256(keccak256(abi.encodePacked(actorSeed))) | 1);
        vm.assume(actor != address(c));
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        uint256 balBefore = actor.balance;
        vm.prank(actor);
        c.withdrawAll();
        uint256 balAfter = actor.balance;
        assertTrue(balAfter == balBefore + amount);
    }
}
